"""Fragments rédigés pour DX7 ; chaque paragraphe porte ses preuves lues."""
from pathlib import Path
from html import escape
import json, re

ROOT = Path(__file__).parent
P = {x['id']: x for x in json.loads((ROOT/'paquet.json').read_text())['passages']}
def refs(ids):
    for i in ids:
        assert i in P, i
    return ''.join(f'<sup class="r"><a href="#sb-{i}">{i}</a></sup>' for i in ids)
def para(text, *ids):
    if 'IL-17' in text and 'eu-asas-eular-2022-detail-18' not in ids:
        ids = (*ids, 'eu-asas-eular-2022-detail-18')
    text = text.replace('actualisées en 2022', 'actualisées').replace('des HUG de 2023', 'des HUG').replace('ASAS–EULAR de 2022', 'ASAS–EULAR')
    sentences = re.split(r'(?<=[.!?])\s+(?=[A-ZÀ-Ý«])', text)
    rendered = []
    for sentence in sentences:
        end = sentence[-1] if sentence[-1] in '.!?' else ''
        body = sentence[:-1] if end else sentence
        rendered.append(escape(body)+refs(ids)+end)
    return '<div class="p">'+' '.join(rendered)+'</div>\n'
def title(text):
    return '<h4><em>'+escape(text)+'</em></h4>\n'
def window(key, label, text, *ids):
    return ('<div class="p"><button class="w" popovertarget="dx7-'+key+'">'+escape(label)+'</button></div>'
            '<div id="dx7-'+key+'" popover class="fenetre">'+title(label)+para(text,*ids)+'</div>\n')
def save(n, text):
    (ROOT/'fragments'/f'p{n:02d}.html').write_text(text)
def table(headers, rows):
    s='<div class="t" style="overflow-x:auto"><table><thead><tr>'+''.join('<th>'+escape(x)+'</th>' for x in headers)+'</tr></thead><tbody>'
    for row in rows:
        s+='<tr>'+''.join('<td>'+para(text,*ids)+'</td>' for text,ids in row)+'</tr>'
    return s+'</tbody></table></div>\n'

save(1,
 title('1.a Une maladie inflammatoire axiale dont la forme radiographique est définie')+
 para('Les recommandations ASAS–EULAR actualisées en 2022 définissent la spondylarthrite axiale comme une maladie rhumatismale inflammatoire chronique qui touche préférentiellement le squelette axial. Elles distinguent la forme radiographique, également appelée spondylarthrite ankylosante, et la forme non radiographique selon la présence ou l’absence de sacro-iliite radiographique. La différence terminologique porte donc sur une constatation d’imagerie, dans un spectre de maladie commun.', 'eu-asas-eular-2022-detail-5')+
 para('La présentation des HUG de 2023 utilise également « maladie de Bechterew » pour la spondylarthrite axiale radiographique. Dans cette monographie, la déformation du dos concerne particulièrement les manifestations structurales avancées : cyphose dorsale, diminution des lordoses et réduction de la mobilité rachidienne. Il faut ainsi relier la posture observée au stade et aux manifestations de la maladie.', 'ch-spa-2023-detail-1','ch-spa-2023-detail-4')+
 para('Les manifestations ne se limitent pas au rachis : une arthrite périphérique, une enthésite ou une dactylite peut accompagner l’atteinte axiale. Une uvéite antérieure aiguë, un psoriasis et une maladie inflammatoire de l’intestin appartiennent aux manifestations extramusculosquelettiques décrites par ASAS–EULAR. Leur recherche fait donc partie de la caractérisation de la maladie, même lorsque le motif de consultation est une posture anormale.', 'eu-asas-eular-2022-detail-5','eu-asas-eular-2022-detail-24')+
 title('1.b Le dommage structural et l’activité inflammatoire répondent à des questions différentes')+
 para('L’inflammation axiale peut être appréciée par l’IRM des articulations sacro-iliaques ou du rachis, tandis que les radiographies du rachis renseignent sur les dommages structuraux. La présence de syndesmophytes possède une valeur pronostique pour la formation ultérieure d’autres syndesmophytes. Dès lors, décrire une raideur ou une déformation ne dispense pas d’évaluer séparément l’activité inflammatoire.', 'eu-asas-eular-2022-detail-29')+
 para('La prise en charge cherche à contrôler les symptômes et l’inflammation, à prévenir la progression des dommages et à préserver la fonction et la participation sociale. Cette pluralité d’objectifs explique pourquoi la qualité de vie ne se résume ni à une image radiographique ni à un seul score de douleur. Le raisonnement clinique doit donc conserver ces domaines distincts au moment de définir le traitement.', 'eu-asas-eular-2022-detail-20')+
 window('radiographique','Que signifie « radiographique » ?', 'Le terme distingue les patients présentant une sacro-iliite radiographique de ceux qui n’en présentent pas. Les formes radiographique et non radiographique appartiennent au même spectre et présentent de nombreuses ressemblances cliniques, y compris pour le retentissement et la réponse thérapeutique. Cette distinction ne transforme donc pas automatiquement une image en mesure de toute la sévérité clinique.', 'eu-asas-eular-2022-detail-5')+
 title('1.c Les mots qui orientent correctement l’examen')+
 para('Une enthésite correspond à une inflammation d’une enthèse, c’est-à-dire d’une zone d’insertion sur l’os, notamment tendineuse ou ligamentaire. Les HUG décrivent également la diminution de mobilité, les enthèses sensibles, les articulations périphériques douloureuses ou gonflées et les manifestations cutanées. Ces termes désignent des constatations différentes ; il faut donc préciser ce qui a effectivement été recherché et trouvé.', 'ch-spa-2023-detail-2','ch-spa-2023-detail-4')+
 para('Une rachialgie inflammatoire est un ensemble de caractéristiques cliniques : douleurs nocturnes, raideur matinale et amélioration par l’activité figurent dans la présentation des HUG. Cependant, le diagnostic de spondylarthrite axiale doit être posé ou confirmé par un rhumatologue, à partir de la présentation clinique, des examens biologiques et de l’imagerie, après exclusion d’explications plus probables. Le qualificatif « inflammatoire » ne suffit donc pas à lui seul à nommer la maladie.', 'ch-spa-2023-detail-1','eu-asas-eular-2022-detail-25')+
 para('Les critères de classification ASAS servent à constituer des populations homogènes pour la recherche. ASAS–EULAR précise qu’ils ne doivent pas être utilisés comme fondement automatique du diagnostic individuel. Ainsi, l’étudiant doit distinguer la classification d’une cohorte, la confirmation clinique de la maladie et l’évaluation de son activité.', 'eu-asas-eular-2022-detail-25','eu-asas-eular-2022-detail-28')+
 window('diagnostic','Pourquoi une classification ne suffit-elle pas ?', 'Le diagnostic spécialisé confronte symptômes, biologie et imagerie et recherche les diagnostics alternatifs plus probables. Les critères de classification répondent à un besoin de recherche et leur satisfaction ne remplace pas cette démarche. Une liste de critères remplie ne dispense donc pas de l’interprétation clinique.', 'eu-asas-eular-2022-detail-25')
)

save(2,
 title('2.a Définir la population avant de commenter un chiffre')+
 para('Le colloque des HUG de 2023 présente une prévalence de 1 à 2 % pour les spondylarthropathies dans leur ensemble. Ce chiffre apparaît dans une présentation qui distingue ensuite des formes axiales, périphériques et apparentées. Il ne doit donc pas être attribué aux seules spondylarthrites axiales radiographiques avec ankylose et déformation du dos.', 'ch-spa-2023-detail-1','ch-spa-2023-detail-7')+
 para('Les recommandations européennes ASAS–EULAR traitent ensemble les formes axiales radiographiques et non radiographiques, car elles appartiennent au même spectre. En conséquence, une donnée portant sur l’ensemble de la spondylarthrite axiale n’est pas automatiquement une donnée sur le sous-groupe présentant une déformation structurale avancée. Le dénominateur doit rester explicite lorsqu’une donnée épidémiologique est utilisée.', 'eu-asas-eular-2022-detail-5')+
 para('Les HUG rapportent une représentation féminine plus importante dans les formes non radiographiques que dans les formes radiographiques. Cette observation aide à éviter une représentation clinique limitée à un seul sexe. Elle doit cependant rester rattachée à la comparaison des sous-types présentée dans cette source.', 'ch-spa-2023-detail-2')+
 title('2.b Le terrain génétique modifie la suspicion sans devenir un diagnostic')+
 para('La présentation des HUG décrit HLA-B27 comme un antigène de classe I et indique que seule une minorité des personnes porteuses développe une spondylarthropathie. La présence de cet antigène doit donc être interprétée dans le contexte clinique. Elle n’équivaut pas à une preuve individuelle d’ankylose inflammatoire ni à une explication suffisante de toute posture anormale.', 'ch-spa-2023-detail-3','eu-asas-eular-2022-detail-25')+
 para('Le même support rapporte que l’âge de début est plus tardif chez les patients HLA-B27 négatifs. Ainsi, le terrain génétique et le profil clinique peuvent varier, et une démarche fondée sur un portrait unique risque de négliger certaines présentations. La confirmation spécialisée repose néanmoins sur l’ensemble clinique, biologique et radiologique plutôt que sur ce seul terrain.', 'ch-spa-2023-detail-2','eu-asas-eular-2022-detail-25')+
 window('denominateur','Prévalence de la famille et fréquence de la déformation', 'La catégorie des spondylarthropathies est plus large que la spondylarthrite axiale radiographique. Les formes axiales radiographiques et non radiographiques sont elles-mêmes distinguées. Le chiffre global présenté par les HUG ne décrit donc pas la fréquence de l’ankylose déformante chez tous les patients qui consultent pour une anomalie de posture.', 'ch-spa-2023-detail-1','eu-asas-eular-2022-detail-5')+
 title('2.c Une histoire naturelle qui exige de suivre plusieurs domaines')+
 para('Les lésions structurales progressent lentement et les syndesmophytes déjà présents signalent un risque de formation de nouveaux syndesmophytes. La recommandation d’espacer les radiographies de surveillance structurale s’inscrit dans cette lenteur d’évolution. Elle ne doit pas être appliquée à une douleur nouvelle faisant suspecter une fracture, qui relève d’une autre démarche d’imagerie.', 'eu-asas-eular-2022-detail-29','eu-asas-eular-2022-detail-17')+
 para('L’activité évaluée par ASDAS est associée longitudinalement à la formation de syndesmophytes. Cette relation soutient la surveillance de l’inflammation, mais elle ne signifie pas qu’un score isolé résume la totalité du dommage futur. Les recommandations conservent donc une évaluation clinique complète, intégrant symptômes, fonction, biologie et imagerie adaptée.', 'eu-asas-eular-2022-detail-28','eu-asas-eular-2022-detail-26')+
 para('Le tabagisme est associé à l’inflammation rachidienne et à la progression de la maladie. ASAS–EULAR recommande son arrêt, tout en précisant que le bénéfice propre du sevrage sur l’évolution de la spondylarthrite n’a pas fait l’objet d’une investigation formelle dans les données discutées. Il faut ainsi présenter l’association et la recommandation sans inventer un effet chiffré du sevrage sur l’ankylose.', 'eu-asas-eular-2022-detail-33')+
 title('2.d Le retentissement individuel et social appartient à l’évaluation')+
 para('La maladie peut altérer la productivité au travail et entraîner présentéisme, arrêts de travail ou incapacité. ASAS–EULAR considère ces conséquences personnelles et économiques comme une composante de la prise en charge. L’interrogatoire doit donc documenter les tâches devenues difficiles et les effets sur la participation, au-delà de la seule intensité douloureuse.', 'eu-asas-eular-2022-detail-22','eu-asas-eular-2022-detail-20')+
 para('La prise en charge vise une qualité de vie durable, ce qui associe contrôle de l’inflammation, préservation de la fonction et participation sociale. Les coûts des soins et des traitements doivent être pris en considération, mais les recommandations précisent qu’ils ne doivent pas supplanter les meilleurs soins pour la personne. Cette articulation explique l’intérêt d’une décision partagée et d’une coordination par le rhumatologue.', 'eu-asas-eular-2022-detail-20','eu-asas-eular-2022-detail-23','eu-asas-eular-2022-detail-21')
)

save(3,
 title('3.a De l’enthèse à l’inflammation chronique')+
 para('Le modèle présenté par les HUG place l’enthèse au centre de la physiopathologie. Des contraintes mécaniques et biologiques peuvent participer au stress enthésique ; les voies inflammatoires et les mécanismes de remodelage osseux sont ensuite mis en relation. Cette présentation relie ainsi le site d’insertion tissulaire aux manifestations inflammatoires et aux modifications structurales.', 'ch-spa-2023-detail-2','ch-spa-2023-detail-3')+
 para('Le schéma des HUG fait intervenir des cytokines inflammatoires et des voies de remodelage, notamment TNF, IL-1, IL-23, WNT et BMP, dans un réseau associé à l’inflammation, aux érosions, à la prolifération osseuse et à l’ankylose. Il ne faut donc pas réduire la déformation à une simple contracture musculaire. Le mécanisme associe inflammation et remaniement de tissus appartenant au squelette axial.', 'ch-spa-2023-detail-3')+
 para('Les susceptibilités génétiques décrites dans ce schéma comprennent HLA-B27 et d’autres variants. Toutefois, la présence d’un facteur de susceptibilité ne signifie pas qu’un individu développe nécessairement la maladie. Le passage du terrain à la manifestation clinique doit donc être apprécié avec les signes et les examens, plutôt que déduit du seul résultat génétique.', 'ch-spa-2023-detail-3','eu-asas-eular-2022-detail-25')+
 window('enthese','L’enthèse : un site d’insertion', 'Une enthèse est une zone d’insertion sur l’os ; une enthésite en désigne l’inflammation. Les HUG citent notamment les insertions tendineuses et ligamentaires. Une douleur d’insertion recherchée à l’examen doit ainsi être distinguée d’une douleur articulaire et replacée dans les autres manifestations de la maladie.', 'ch-spa-2023-detail-2','ch-spa-2023-detail-4')+
 title('3.b Relier les manifestations à ce qui peut être exploré')+
 para('La douleur inflammatoire, la raideur et la fatigue contribuent au retentissement de l’activité de la maladie. Leur suivi est complété par la CRP dans l’ASDAS, alors que le BASDAI traduit la perspective du patient. Cette différence explique pourquoi les deux instruments ne sont pas interchangeables pour tous les usages de surveillance.', 'eu-asas-eular-2022-detail-28')+
 para('L’IRM peut montrer une inflammation axiale des sacro-iliaques ou du rachis. Cependant, la concordance entre les mesures cliniques d’activité et l’inflammation observée à l’IRM reste modeste. L’examen peut donc aider lorsque l’origine des plaintes ou la persistance de l’inflammation est incertaine, sans être imposé de manière répétée à chaque contrôle.', 'eu-asas-eular-2022-detail-29')+
 para('Les radiographies du rachis servent à apprécier les lésions structurales, notamment les syndesmophytes. Ainsi, une mesure d’activité et une image de dommage répondent à des questions complémentaires : l’une participe à l’appréciation de l’inflammation actuelle, l’autre décrit des modifications structurales. Cette distinction permet d’éviter une escalade thérapeutique fondée uniquement sur l’aspect de la posture.', 'eu-asas-eular-2022-detail-28','eu-asas-eular-2022-detail-29','eu-asas-eular-2022-detail-30')+
 title('3.c La déformation modifie la fonction et les risques à rechercher')+
 para('Dans les formes avancées décrites aux HUG, la mobilité globale du rachis diminue et la cyphose dorsale s’accentue ; les lordoses lombaire et cervicale peuvent diminuer. L’examen doit donc analyser la position et la mobilité de plusieurs régions plutôt que constater seulement un « dos rond ». Les adaptations décrites incluent également des modifications cranio-cervicales et des flexums des membres inférieurs.', 'ch-spa-2023-detail-4','ch-spa-2023-detail-5')+
 para('La diminution de l’expansion thoracique et une respiration davantage abdominale figurent parmi les manifestations avancées. Cette association rattache la déformation rachidienne à une limitation fonctionnelle qui dépasse l’esthétique du dos. Elle justifie d’intégrer l’observation thoracique à l’examen régional et au retentissement décrit par le patient.', 'ch-spa-2023-detail-5')+
 para('Un changement important dans le cours de la maladie doit conduire à rechercher une cause autre qu’une augmentation de l’inflammation, notamment une fracture rachidienne. La recommandation ASAS–EULAR demande alors une évaluation appropriée incluant l’imagerie. Une nouvelle douleur sur un rachis déformé ne doit donc pas être considérée d’emblée comme une poussée habituelle.', 'eu-asas-eular-2022-detail-17')+
 title('3.d Le mécanisme guide une stratégie combinée')+
 para('Les AINS constituent le traitement pharmacologique de première intention de la douleur et de la raideur, après appréciation du rapport bénéfice–risque. Une activité persistante malgré les traitements conventionnels peut conduire à discuter des traitements ciblés avec le rhumatologue. L’exercice et la physiothérapie conservent leur place propre, car leurs bénéfices ne dépendent pas uniquement de l’effet des médicaments.', 'eu-asas-eular-2022-detail-15','eu-asas-eular-2022-detail-16','eu-asas-eular-2022-detail-32')+
 para('Les traitements destinés à une arthrite périphérique ne s’appliquent pas automatiquement à une atteinte purement axiale. ASAS–EULAR déconseille en règle générale les traitements de fond synthétiques conventionnels pour la maladie purement axiale et distingue le cas d’une arthrite périphérique. La localisation de l’inflammation change donc la pertinence de la stratégie thérapeutique.', 'eu-asas-eular-2022-detail-16')+
 para('Une correction chirurgicale de la déformation rachidienne peut être envisagée dans un centre spécialisé lorsque la déformation est sévère et invalidante. Cette option correspond à une indication fonctionnelle et structurale spécialisée ; elle ne remplace pas l’évaluation de l’activité inflammatoire ni les autres composantes du traitement. La décision reste inscrite dans la prise en charge individualisée.', 'eu-asas-eular-2022-detail-17','eu-asas-eular-2022-detail-24')
)

save(4,
 title('4.a 🚩 Une rupture du cours habituel impose de rechercher une fracture')+
 para('Chez une personne dont le rachis est ankylosé, une douleur nouvelle ou une modification importante du tableau doit faire suspecter une fracture, même après un traumatisme mineur. ASAS–EULAR souligne que les fractures peuvent alors avoir un pronostic plus défavorable que dans la population générale. La première décision consiste donc à rechercher cette complication plutôt qu’à augmenter automatiquement le traitement d’une poussée supposée.', 'eu-asas-eular-2022-detail-54')+
 para('Lorsqu’une fracture est suspectée, la recommandation prévoit une imagerie adaptée par IRM et/ou tomodensitométrie et, selon la situation, l’avis d’un chirurgien rachidien expérimenté. L’imagerie poursuit ici un objectif différent de la surveillance lente des syndesmophytes. Il faut ainsi distinguer le bilan d’un événement nouveau du calendrier habituel de suivi de la maladie.', 'eu-asas-eular-2022-detail-54','eu-asas-eular-2022-detail-29')+
 window('fracture','La douleur nouvelle sur rachis ankylosé', 'Un traumatisme de faible intensité peut suffire à provoquer une fracture dans ce contexte. Une rupture du cours clinique impose une évaluation recherchant des causes autres que l’inflammation. La recommandation cite l’IRM et/ou le CT, ainsi que le recours possible à un chirurgien rachidien expérimenté.', 'eu-asas-eular-2022-detail-54')+
 title('4.b La confirmation revient à une démarche clinique spécialisée')+
 para('La confirmation de la spondylarthrite axiale appartient au rhumatologue et combine la présentation clinique, les examens biologiques et l’imagerie. Les diagnostics alternatifs plus probables doivent être exclus. Le raisonnement ne consiste donc pas à additionner des critères de classification puis à traiter leur résultat comme une certitude diagnostique.', 'eu-asas-eular-2022-detail-25')+
 para('L’interrogatoire cherche des douleurs nocturnes, une raideur matinale et une amélioration par l’activité. L’examen recherche ensuite la limitation de mobilité et les autres manifestations de spondylarthropathie. Ces éléments orientent la suspicion, mais leur interprétation reste intégrée à la biologie et à l’imagerie plutôt qu’isolée de celles-ci.', 'ch-spa-2023-detail-1','ch-spa-2023-detail-4','eu-asas-eular-2022-detail-25')+
 para('Les HUG proposent une biologie inflammatoire et la recherche de HLA-B27 selon le contexte, ainsi qu’une radiographie du bassin et une IRM sacro-iliaque adaptée. Le support attire aussi l’attention sur la probabilité pré-test et les faux positifs de l’IRM. Une anomalie isolée doit donc être confrontée à la question clinique avant de conclure.', 'ch-spa-2023-detail-5','ch-spa-2023-detail-7')+
 title('4.c Les comparaisons qui évitent les confusions de conduite')+
 table(['Hypothèse ou problème','Élément discriminant','Piège','Conséquence'],[
 [('Une fracture peut compliquer un rachis ankylosé.',['eu-asas-eular-2022-detail-54']),('Une modification importante du cours clinique, parfois après traumatisme mineur, doit la faire rechercher.',['eu-asas-eular-2022-detail-54']),('Toute nouvelle douleur ne correspond pas nécessairement à une poussée inflammatoire.',['eu-asas-eular-2022-detail-54']),('Une IRM et/ou un CT sont indiqués selon la suspicion, avec avis rachidien expérimenté si nécessaire.',['eu-asas-eular-2022-detail-54'])],
 [('Une rachialgie mécanique peut orienter vers une autre explication.',['ch-spa-2023-detail-1']),('Les HUG opposent notamment douleur après activité et en fin de journée au profil inflammatoire soulagé par l’activité.',['ch-spa-2023-detail-1']),('Le profil horaire ne remplace pas le diagnostic intégré.',['eu-asas-eular-2022-detail-25']),('Les explications alternatives plus probables sont recherchées avant de confirmer la spondylarthrite.',['eu-asas-eular-2022-detail-25'])],
 [('L’arthrose et la maladie hyperostosique peuvent entrer dans la comparaison radiographique.',['ch-spa-2023-detail-5']),('Les HUG distinguent syndesmophytes, ostéophytes et ossifications hyperostosiques dans leur présentation du rachis.',['ch-spa-2023-detail-5']),('Une production osseuse visible ne porte pas automatiquement le même diagnostic.',['ch-spa-2023-detail-5','eu-asas-eular-2022-detail-25']),('L’imagerie est interprétée avec la clinique spécialisée et les autres résultats.',['eu-asas-eular-2022-detail-25'])],
 [('Une comorbidité peut contribuer aux plaintes persistantes.',['eu-asas-eular-2022-detail-49']),('La fibromyalgie, la dépression et l’arthrose peuvent majorer l’activité ressentie et modifier les résultats du traitement.',['eu-asas-eular-2022-detail-49']),('Un score de symptômes élevé ne prouve pas seul une inflammation résiduelle.',['eu-asas-eular-2022-detail-30','eu-asas-eular-2022-detail-49']),('Le diagnostic et les comorbidités sont réévalués avant une escalade immunosuppressive automatique.',['eu-asas-eular-2022-detail-48','eu-asas-eular-2022-detail-49'])]
 ])+
 title('4.d L’échec thérapeutique réouvre la question diagnostique')+
 para('L’absence de réponse à un traitement doit faire réévaluer le diagnostic et rechercher les comorbidités. ASAS–EULAR décrit explicitement le risque de surdiagnostic et de surtraitement, notamment dans des présentations moins classiques. Changer immédiatement de traitement immunosuppresseur ne constitue donc pas la seule réponse à des plaintes persistantes.', 'eu-asas-eular-2022-detail-48')+
 para('L’intensification thérapeutique suppose que le patient et le médecin soient convaincus de la persistance d’une activité inflammatoire. Le score sert de guide, mais les facteurs contextuels susceptibles de le modifier doivent être pris en compte. Cette étape permet de relier la décision à la cause de la plainte plutôt qu’à la seule valeur d’un questionnaire.', 'eu-asas-eular-2022-detail-30','eu-asas-eular-2022-detail-49')
)

save(5,
 title('5.a Reconstituer le profil et l’évolution des douleurs')+
 para('L’interrogatoire précise le moment d’apparition de la douleur, son horaire, son rapport à l’activité et la durée de la raideur matinale. Le profil inflammatoire décrit aux HUG comprend des douleurs nocturnes, notamment en fin de nuit, une raideur matinale prolongée et une amélioration à l’activité. Ces questions cherchent donc une cohérence clinique plutôt qu’un seul mot-clé.', 'ch-spa-2023-detail-1','ch-spa-2023-detail-3')+
 para('Il faut demander si les douleurs du bassin changent de côté, sont bilatérales ou s’accompagnent d’irradiations décrites comme pseudo-sciatalgies. Le support des HUG inclut ces présentations dans l’atteinte inflammatoire axiale. L’irradiation doit ainsi être décrite précisément au lieu de transformer toute douleur projetée en diagnostic mécanique identique.', 'ch-spa-2023-detail-1','ch-spa-2023-detail-3')+
 para('La fatigue, une perte de poids et parfois la fièvre figurent parmi les symptômes généraux décrits. Ils contribuent à caractériser le tableau mais ne suffisent pas à confirmer une spondylarthrite. En effet, la démarche diagnostique spécialisée doit toujours tenir compte d’autres causes plus probables lorsque la présentation l’impose.', 'ch-spa-2023-detail-3','eu-asas-eular-2022-detail-25')+
 title('5.b Rechercher les manifestations que le patient ne relie pas spontanément au dos')+
 para('Des douleurs du talon peuvent orienter vers une enthésite, tandis que des douleurs ou gonflements articulaires périphériques évoquent une atteinte périphérique associée. Les HUG décrivent également des douleurs de la paroi thoracique antérieure. Ces questions élargissent donc l’histoire clinique à des sites qui peuvent éclairer l’atteinte axiale.', 'ch-spa-2023-detail-3','ch-spa-2023-detail-4')+
 para('Les antécédents d’œil rouge ou d’uvéite, de psoriasis cutané ou unguéal et de maladie inflammatoire intestinale doivent être recherchés. Leur présence contribue à la caractérisation de la spondylarthrite et peut changer le choix du traitement. Il est donc utile de préciser le caractère récurrent d’une uvéite et l’activité d’une atteinte digestive, plutôt que de noter seulement leur existence ancienne.', 'ch-spa-2023-detail-4','eu-asas-eular-2022-detail-24','eu-asas-eular-2022-detail-47')+
 para('Une maladie inflammatoire intestinale active oriente la stratégie différemment d’un psoriasis important : ASAS–EULAR privilégie un anticorps monoclonal anti-TNF en présence d’une atteinte intestinale active ou d’uvéites récidivantes, tandis qu’un inhibiteur d’IL-17 peut être préféré pour un psoriasis significatif. L’interrogatoire sur les manifestations associées possède donc une conséquence thérapeutique concrète.', 'eu-asas-eular-2022-detail-47')+
 window('extraaxial','Pourquoi interroger la peau, les yeux et l’intestin ?', 'Les manifestations extramusculosquelettiques font partie de la caractérisation de la maladie. Leur nature et leur activité influencent le choix des traitements ciblés ; toutes les molécules efficaces sur l’axe ne possèdent pas le même intérêt pour une uvéite, une maladie intestinale ou un psoriasis.', 'eu-asas-eular-2022-detail-24','eu-asas-eular-2022-detail-47')+
 title('5.c Identifier ce qui rompt l’histoire habituelle')+
 para('Une nouvelle douleur, une aggravation importante ou un traumatisme même mineur doivent être distingués de la fluctuation habituelle des symptômes. Sur un rachis ankylosé, cette distinction sert à ne pas méconnaître une fracture. La question sur le traumatisme doit donc rester ouverte aux événements que le patient juge trop faibles pour être pertinents.', 'eu-asas-eular-2022-detail-54')+
 para('Lorsqu’une modification significative est identifiée, la conduite consiste à rechercher une autre cause que l’inflammation et à réaliser l’imagerie appropriée. Le patient ne doit pas être simplement replacé dans son calendrier de contrôle structural habituel. Le contexte de l’événement nouveau détermine une nouvelle question diagnostique.', 'eu-asas-eular-2022-detail-54','eu-asas-eular-2022-detail-29')+
 table(['Information recherchée','Signification','Décision associée'],[
 [('Le patient décrit une douleur nouvelle après un événement mécanique mineur.',['eu-asas-eular-2022-detail-54']),('Une fracture est possible sur un rachis ankylosé malgré la faible intensité du traumatisme.',['eu-asas-eular-2022-detail-54']),('La situation requiert une évaluation adaptée, avec IRM et/ou CT et recours spécialisé selon les constatations.',['eu-asas-eular-2022-detail-54'])],
 [('Les plaintes persistent malgré un traitement supposé adapté.',['eu-asas-eular-2022-detail-48']),('Le diagnostic ou une comorbidité peut expliquer l’absence de réponse.',['eu-asas-eular-2022-detail-48','eu-asas-eular-2022-detail-49']),('La réévaluation précède un changement automatique d’immunosuppression.',['eu-asas-eular-2022-detail-48'])],
 [('Une uvéite récidivante ou une maladie intestinale active est rapportée.',['eu-asas-eular-2022-detail-47']),('La manifestation associée influence le choix de la classe thérapeutique.',['eu-asas-eular-2022-detail-47']),('Le rhumatologue intègre cette atteinte dans la décision et la coordination des soins.',['eu-asas-eular-2022-detail-14','eu-asas-eular-2022-detail-47'])]
 ])+
 title('5.d Documenter les traitements, le fonctionnement et les attentes')+
 para('L’histoire des traitements précise les bénéfices, les limitations de tolérance et les raisons de leur arrêt. L’évaluation de l’échec des traitements conventionnels intervient dans les décisions d’escalade, mais elle vient après la confirmation diagnostique. La décision doit également tenir compte des risques individuels et des manifestations associées.', 'eu-asas-eular-2022-detail-38','eu-asas-eular-2022-detail-41','eu-asas-eular-2022-detail-24')+
 para('Les difficultés de travail, les activités devenues impossibles et les objectifs du patient complètent l’évaluation. La prise en charge vise la fonction et la participation sociale et repose sur une décision partagée. Ainsi, demander ce que la personne souhaite pouvoir refaire constitue une manière concrète de relier son expérience aux objectifs thérapeutiques.', 'eu-asas-eular-2022-detail-20','eu-asas-eular-2022-detail-21','eu-asas-eular-2022-detail-22')
)

save(6,
 title('6.a Examiner la posture dans son ensemble')+
 para('L’examen décrit la cyphose dorsale, les lordoses lombaire et cervicale et la position cranio-cervicale. Les HUG décrivent dans les formes avancées une cyphose dorsale accrue, une diminution des lordoses et des adaptations cranio-cervicales. La posture doit donc être analysée région par région plutôt que résumée à une seule impression de flexion.', 'ch-spa-2023-detail-4')+
 para('L’observation inclut les hanches et les genoux, car des flexums sont décrits dans les formes avancées. Elle inclut aussi l’expansion thoracique et la participation abdominale à la respiration. Ces constatations aident à comprendre le retentissement de la déformation sur l’ensemble du mouvement et de la fonction.', 'ch-spa-2023-detail-5')+
 para('Une modification douloureuse importante du tableau doit interrompre l’interprétation habituelle d’une simple raideur chronique et faire rechercher une fracture. La priorité devient alors l’évaluation adaptée et l’imagerie, notamment sur un rachis ankylosé. L’examen de suivi ne doit donc pas masquer la recherche d’une complication nouvelle.', 'eu-asas-eular-2022-detail-54')+
 title('6.b Quantifier la mobilité avec une technique explicitée')+
 para('La présentation des HUG décrit le test de Schober lombaire en prenant le repère L4–L5, puis des repères à 10 cm au-dessus et 5 cm au-dessous. Une augmentation normalement supérieure à 5 cm est indiquée pour cette technique. La mesure doit donc être rapportée avec la méthode employée, plutôt qu’avec un chiffre dépourvu de repères anatomiques.', 'ch-spa-2023-detail-4')+
 para('Le test participe à l’évaluation de la mobilité lombaire, mais le suivi clinique recommandé ne repose pas sur lui seul. ASAS–EULAR inclut la mobilité rachidienne, les symptômes rapportés, la fonction, la biologie et l’évaluation des manifestations associées. La diminution d’une mesure doit ainsi être replacée dans l’ensemble du bilan.', 'ch-spa-2023-detail-4','eu-asas-eular-2022-detail-28','eu-asas-eular-2022-detail-26')+
 window('schober','Repères du Schober décrits par les HUG', 'Dans la méthode présentée, le repérage utilise L4–L5, une marque 10 cm au-dessus et une marque 5 cm au-dessous. L’allongement normalement attendu est supérieur à 5 cm. Ces nombres appartiennent à cette technique de mesure ; ils ne constituent pas, à eux seuls, des critères diagnostiques de spondylarthrite.', 'ch-spa-2023-detail-4','eu-asas-eular-2022-detail-25')+
 title('6.c Rechercher les enthèses et les articulations périphériques')+
 para('La palpation des enthèses recherche une sensibilité, parfois accompagnée d’une tuméfaction. L’examen des articulations périphériques recherche douleur et synovite ; une dactylite peut aussi être observée. Ces signes sont recherchés séparément, car une atteinte périphérique associée peut modifier les options thérapeutiques.', 'ch-spa-2023-detail-4','eu-asas-eular-2022-detail-37')+
 para('Les HUG décrivent notamment des talalgies dans le tableau clinique. Leur recherche s’inscrit donc dans l’examen des sites enthésiques, en parallèle de l’étude du rachis. Cependant, l’ensemble des constatations doit rester interprété dans la démarche clinique spécialisée, qui tient compte des diagnostics alternatifs.', 'ch-spa-2023-detail-3','eu-asas-eular-2022-detail-25')+
 para('L’examen périphérique complète les questionnaires de douleur et de fatigue : ASAS–EULAR inclut notamment le décompte des articulations gonflées dans les domaines du suivi. Cette complémentarité évite de remplacer l’examen clinique par une simple impression globale d’activité élevée.', 'eu-asas-eular-2022-detail-28')+
 title('6.d Examiner les manifestations associées et leur retentissement')+
 para('L’inspection cutanée et unguéale recherche des éléments de psoriasis, tandis que l’interrogatoire et l’observation orientent la recherche d’une atteinte oculaire ou digestive. Le support des HUG associe explicitement psoriasis, uvéite et colite au spectre clinique. Leur caractérisation est donc pertinente même lorsque la consultation concerne surtout la posture du dos.', 'ch-spa-2023-detail-4','eu-asas-eular-2022-detail-24')+
 para('La mobilité, la posture et les autres constatations sont rapprochées de la fonction rapportée par le patient. ASAS–EULAR distingue les mesures de douleur, de raideur, de fatigue et de fonction physique, et propose aussi une appréciation plus globale de la santé. Une limitation observée doit ainsi être reliée à ses conséquences quotidiennes plutôt que rester un résultat abstrait.', 'eu-asas-eular-2022-detail-28')+
 title('6.e Interpréter la concordance et les discordances')+
 para('Une activité ressentie importante peut être influencée par des comorbidités comme l’arthrose, une fibromyalgie ou une dépression. L’examen et les mesures objectives aident à analyser cette situation, sans nier les symptômes. Les recommandations demandent de tenir compte de ces facteurs avant de décider que toute plainte résiduelle impose davantage d’immunosuppression.', 'eu-asas-eular-2022-detail-49','eu-asas-eular-2022-detail-30')+
 para('Une déformation sévère et invalidante peut conduire à une évaluation chirurgicale spécialisée. La décision ne se déduit pas d’une seule mesure de posture ; elle est reliée à la sévérité et au handicap. De même, une atteinte de hanche douloureuse et destructrice relève d’une évaluation spécifique plutôt que d’une attribution automatique de toute limitation au rachis.', 'eu-asas-eular-2022-detail-53')
)

save(7,
 title('7.1 Le syndrome axial inflammatoire')+
 para('Le patient peut décrire des rachialgies nocturnes, une raideur matinale et une amélioration par l’activité, avec des douleurs du bassin parfois à bascule. Les HUG opposent ce profil au profil mécanique plutôt aggravé par l’activité et en fin de journée. L’approche syndromique commence donc par la cohérence entre horaire, raideur et réponse au mouvement.', 'ch-spa-2023-detail-1','ch-spa-2023-detail-3')+
 para('À ces symptômes s’ajoutent les constatations de mobilité rachidienne réduite et les résultats biologiques ou d’imagerie adaptés. La synthèse spécialisée doit néanmoins exclure les diagnostics alternatifs plus probables. Le syndrome inflammatoire sert ainsi d’orientation clinique, sans devenir une confirmation autonome de la maladie.', 'ch-spa-2023-detail-4','eu-asas-eular-2022-detail-25')+
 title('7.2 Le syndrome de déformation et de limitation structurale')+
 para('Les signes physiques des formes avancées comprennent une cyphose dorsale accrue, une diminution des lordoses et une mobilité globale réduite. Des adaptations cranio-cervicales et des flexums de hanche ou de genou peuvent compléter cette présentation. Le clinicien recherche donc une organisation posturale globale et son retentissement fonctionnel.', 'ch-spa-2023-detail-4','ch-spa-2023-detail-5')+
 para('Le dommage structural est apprécié notamment sur les radiographies, tandis que l’inflammation peut être explorée par l’IRM lorsqu’une question clinique le justifie. Cette distinction aide à comprendre pourquoi une limitation persiste parfois dans un tableau dont l’activité doit être évaluée séparément. La fonction demeure un domaine de suivi à part entière.', 'eu-asas-eular-2022-detail-29','eu-asas-eular-2022-detail-28')+
 window('syndesmophytes','Dommage structural et syndesmophytes', 'Les radiographies permettent d’apprécier le dommage structural rachidien. La présence de syndesmophytes possède une valeur pronostique pour la formation de nouvelles lésions du même type. La surveillance de ces modifications lentes répond à une autre question que la recherche urgente d’une fracture.', 'eu-asas-eular-2022-detail-29','eu-asas-eular-2022-detail-54')+
 title('7.3 Le syndrome périphérique associé')+
 para('Les douleurs enthésiques, les arthrites périphériques et les dactylites élargissent le tableau au-delà du squelette axial. Les HUG décrivent les enthèses sensibles ou gonflées et les articulations périphériques douloureuses ou synovitiques. Il faut donc relier les plaintes localisées à des signes physiques décrits avec précision.', 'ch-spa-2023-detail-4','eu-asas-eular-2022-detail-5')+
 para('L’identification d’une arthrite périphérique possède une conséquence thérapeutique : la place des traitements de fond synthétiques conventionnels n’est pas la même que dans une maladie purement axiale. ASAS–EULAR distingue explicitement ces deux situations, notamment pour la sulfasalazine. Le diagnostic syndromique contribue ainsi à choisir une stratégie adaptée au territoire atteint.', 'eu-asas-eular-2022-detail-37')+
 title('7.4 Les manifestations extramusculosquelettiques')+
 para('Une uvéite, un psoriasis et une maladie inflammatoire intestinale sont les manifestations extramusculosquelettiques mises en avant dans les recommandations. Leur activité et leur histoire doivent être documentées, car elles influencent le traitement. Une uvéite récidivante et un psoriasis significatif ne conduisent donc pas nécessairement à privilégier la même classe.', 'eu-asas-eular-2022-detail-24','eu-asas-eular-2022-detail-47')+
 table(['Ensemble clinique','Signes fonctionnels recherchés','Signes et explorations associés'],[
 [('Le tableau axial peut évoquer une inflammation.',['ch-spa-2023-detail-1']),('Le patient décrit horaire nocturne, raideur matinale et réponse à l’activité.',['ch-spa-2023-detail-1']),('La mobilité, la biologie et l’imagerie sont intégrées dans le diagnostic spécialisé.',['ch-spa-2023-detail-4','eu-asas-eular-2022-detail-25'])],
 [('Le tableau structural comporte une déformation et une limitation.',['ch-spa-2023-detail-4']),('Le retentissement fonctionnel est recueilli avec les symptômes.',['eu-asas-eular-2022-detail-28']),('La posture régionale et les radiographies renseignent sur la déformation et le dommage.',['ch-spa-2023-detail-4','eu-asas-eular-2022-detail-29'])],
 [('Une atteinte périphérique peut accompagner la maladie.',['eu-asas-eular-2022-detail-5']),('Le patient rapporte talalgies et douleurs articulaires périphériques.',['ch-spa-2023-detail-3']),('La palpation recherche enthésite, synovite ou dactylite.',['ch-spa-2023-detail-4'])],
 [('Les manifestations oculaires, cutanées et intestinales complètent le phénotype.',['eu-asas-eular-2022-detail-24']),('Leur histoire et leur activité sont précisées pour guider le traitement.',['eu-asas-eular-2022-detail-24','eu-asas-eular-2022-detail-47']),('La prise en charge est coordonnée selon les manifestations présentes.',['eu-asas-eular-2022-detail-14','eu-asas-eular-2022-detail-24'])]
 ])+
 title('7.5 La complication nouvelle ne se fond pas dans le syndrome chronique')+
 para('Une douleur nouvelle après traumatisme mineur ou une rupture importante du cours clinique doit faire rechercher une fracture sur rachis ankylosé. La situation relève d’une évaluation spécifique et d’une imagerie appropriée. Le raisonnement syndromique ne doit donc pas enfermer le patient dans son diagnostic chronique au point de manquer une complication.', 'eu-asas-eular-2022-detail-54')
)

save(8,
 title('8.a Le diagnostic est clinique, biologique et radiologique')+
 para('ASAS–EULAR recommande que le diagnostic de spondylarthrite axiale soit posé ou confirmé par un rhumatologue. Il repose sur une présentation clinique compatible, confrontée à la biologie et à l’imagerie, après exclusion de diagnostics alternatifs plus probables. Il n’existe donc pas, dans cette démarche, de raccourci où un test isolé dispense de la synthèse clinique.', 'eu-asas-eular-2022-detail-25')+
 para('La forme radiographique est distinguée de la forme non radiographique par la sacro-iliite visible à la radiographie. La maladie de Bechterew ou spondylarthrite ankylosante correspond à la forme radiographique. Ces dénominations ne doivent pas être confondues avec un niveau d’activité calculé le jour de la consultation.', 'eu-asas-eular-2022-detail-5','ch-spa-2023-detail-1','eu-asas-eular-2022-detail-28')+
 para('Dans la discussion des critères radiographiques employés pour l’éligibilité thérapeutique, ASAS–EULAR cite la gradation de New York modifiée : une sacro-iliite de grade au moins 2 bilatéralement ou au moins 3 unilatéralement. Cette mention décrit la composante radiographique ; elle ne remplace pas le diagnostic spécialisé ni l’ensemble de l’évaluation clinique.', 'eu-asas-eular-2022-detail-40','eu-asas-eular-2022-detail-25')+
 title('8.b HLA-B27 et l’inflammation doivent être interprétés')+
 para('La présentation des HUG souligne que seule une minorité des personnes HLA-B27 positives développe une spondylarthropathie. Un résultat positif constitue donc un élément du contexte et non une confirmation autonome. Le rhumatologue confronte ce résultat à la présentation et aux examens pertinents.', 'ch-spa-2023-detail-3','eu-asas-eular-2022-detail-25')+
 para('Une CRP élevée et une inflammation sacro-iliaque à l’IRM doivent être attribuables à la spondylarthrite ; les autres causes plausibles doivent être soigneusement exclues. Les HUG insistent également sur la probabilité pré-test et les faux positifs de l’IRM. Ainsi, l’existence d’un signal anormal ne suffit pas à lui attribuer automatiquement la bonne cause.', 'eu-asas-eular-2022-detail-40','ch-spa-2023-detail-7')+
 window('classification','Diagnostic, classification et éligibilité : trois usages', 'Le diagnostic relève d’une synthèse clinique spécialisée. Les critères de classification servent à la recherche. Les critères d’éligibilité à un traitement ciblé interviennent après la confirmation diagnostique et évaluent notamment l’activité, les traitements déjà essayés et les éléments objectifs pertinents. Ces trois usages ne doivent pas être substitués l’un à l’autre.', 'eu-asas-eular-2022-detail-25','eu-asas-eular-2022-detail-38','eu-asas-eular-2022-detail-41')+
 title('8.c Les scores d’activité servent au suivi et à la décision thérapeutique')+
 para('ASAS–EULAR privilégie l’ASDAS, de préférence calculé avec la CRP, pour évaluer l’activité de la spondylarthrite axiale. Ce score associe la perspective du patient à une mesure objective de l’inflammation, alors que le BASDAI reflète la perspective du patient. L’interprétation doit donc préciser l’instrument réellement utilisé.', 'eu-asas-eular-2022-detail-28')+
 para('Pour la discussion d’une escalade thérapeutique, une activité élevée est retenue sur un ASDAS au moins égal à 2,1. Si cette approche n’est pas possible, un BASDAI au moins égal à 4 peut être utilisé comme alternative. Toutefois, la décision ne doit pas reposer sur le score seul : l’avis du rhumatologue et le contexte individuel complètent l’évaluation.', 'eu-asas-eular-2022-detail-41')+
 para('L’absence de réponse, une douleur persistante ou un score élevé doivent aussi faire rechercher des facteurs tels qu’une arthrose, une fibromyalgie ou une dépression. Ces comorbidités peuvent modifier l’activité ressentie et les résultats thérapeutiques. Une valeur de score ne constitue donc pas à elle seule une preuve de persistance d’inflammation justifiant davantage d’immunosuppression.', 'eu-asas-eular-2022-detail-49','eu-asas-eular-2022-detail-30')+
 table(['Élément','Usage correct','Ce qu’il ne remplace pas'],[
 [('La sacro-iliite radiographique caractérise la forme radiographique.',['eu-asas-eular-2022-detail-5']),('La gradation radiographique citée est au moins 2 bilatéralement ou 3 unilatéralement.',['eu-asas-eular-2022-detail-40']),('La synthèse clinique spécialisée reste indispensable.',['eu-asas-eular-2022-detail-25'])],
 [('HLA-B27 contribue au contexte biologique.',['ch-spa-2023-detail-3','ch-spa-2023-detail-5']),('Son résultat est interprété avec la clinique et l’imagerie.',['eu-asas-eular-2022-detail-25']),('La positivité seule ne confirme pas la maladie.',['ch-spa-2023-detail-3','eu-asas-eular-2022-detail-25'])],
 [('L’ASDAS contribue à mesurer l’activité.',['eu-asas-eular-2022-detail-28']),('Le seuil 2,1 intervient dans l’évaluation d’activité élevée pour l’escalade.',['eu-asas-eular-2022-detail-41']),('Il ne constitue pas le diagnostic initial de la spondylarthrite.',['eu-asas-eular-2022-detail-25','eu-asas-eular-2022-detail-38'])],
 [('Les critères de classification constituent un outil de recherche.',['eu-asas-eular-2022-detail-25']),('Ils aident à former des populations homogènes dans les études.',['eu-asas-eular-2022-detail-25']),('Ils ne remplacent pas le diagnostic individuel.',['eu-asas-eular-2022-detail-25'])]
 ])
)

save(9,
 title('9.a La question clinique précède le choix de l’examen')+
 para('La confirmation de la spondylarthrite axiale reste une synthèse spécialisée associant clinique, biologie et imagerie. L’examen demandé doit donc préciser s’il cherche à documenter la maladie, une activité inflammatoire incertaine, le dommage structural ou une complication nouvelle. Ces questions ne requièrent pas toutes le même examen ni le même calendrier.', 'eu-asas-eular-2022-detail-25','eu-asas-eular-2022-detail-29','eu-asas-eular-2022-detail-54')+
 para('Les HUG décrivent une radiographie du bassin de face et une IRM du bassin utilisant notamment des séquences T1, STIR et T2, avec des coupes adaptées aux articulations sacro-iliaques. Le bilan peut être complété selon la présentation par une imagerie du rachis ou d’autres sites. La prescription doit ainsi rester reliée au territoire et à la question diagnostique.', 'ch-spa-2023-detail-5')+
 title('9.b Biologie et première caractérisation')+
 para('Le bilan présenté aux HUG comprend CRP, vitesse de sédimentation et HLA-B27. Selon le tableau, d’autres analyses peuvent répondre à une question différentielle ou à une manifestation associée, par exemple une recherche liée à une présentation périphérique ou à une suspicion de colite. L’ensemble n’est donc pas un panel indifférencié à appliquer sans indication clinique.', 'ch-spa-2023-detail-5')+
 para('La CRP intervient dans l’évaluation de l’activité, notamment à travers l’ASDAS. Cependant, une CRP élevée doit être interprétée comme liée à la spondylarthrite seulement après considération des autres causes plausibles. Le résultat biologique doit ainsi être confronté aux symptômes et aux autres données.', 'eu-asas-eular-2022-detail-28','eu-asas-eular-2022-detail-40')+
 title('9.c L’IRM répond à une incertitude inflammatoire, sans devenir un rituel de suivi')+
 para('L’IRM des sacro-iliaques ou du rachis peut apprécier l’inflammation axiale. ASAS–EULAR ne recommande toutefois pas son utilisation systématique pour la surveillance, car sa valeur dans cet usage reste incertaine et son emploi fréquent est peu réalisable. Elle peut être utile lorsque l’origine des plaintes ou la persistance de l’activité inflammatoire demeure douteuse.', 'eu-asas-eular-2022-detail-29')+
 para('La concordance entre les mesures cliniques d’activité et l’inflammation à l’IRM n’est que modeste. Une discordance doit donc être interprétée plutôt que supprimée par le choix arbitraire d’un résultat préféré. La synthèse cherche à déterminer si une inflammation résiduelle est suffisamment étayée pour guider la décision thérapeutique.', 'eu-asas-eular-2022-detail-29','eu-asas-eular-2022-detail-30')+
 title('9.d Le dommage structural évolue lentement, les complications imposent un autre rythme')+
 para('Les radiographies rachidiennes permettent d’apprécier le dommage structural et les syndesmophytes. Lorsque des radiographies de surveillance structurale sont réalisées, ASAS–EULAR recommande des intervalles d’au moins 2 ans, compte tenu de la lenteur de la progression. Cette règle concerne la surveillance structurale programmée.', 'eu-asas-eular-2022-detail-29')+
 para('En revanche, une suspicion de fracture sur rachis ankylosé appelle une évaluation adaptée avec IRM et/ou CT, selon la situation. Il ne faut pas attendre l’échéance d’un contrôle programmé pour explorer une modification importante du cours clinique. La même personne peut donc nécessiter une imagerie rapprochée pour une complication alors que ses clichés de surveillance structurale restent espacés.', 'eu-asas-eular-2022-detail-54','eu-asas-eular-2022-detail-29')+
 para('Devant des signaux d’alerte neurologiques, comme une rétention urinaire, une anesthésie en selle ou un déficit moteur, la stratégie des HUG demande une imagerie rachidienne sans attendre, si possible une IRM et au minimum un CT, avec avis neurochirurgical. Ces signes changent la priorité de prise en charge ; ils ne relèvent pas d’un simple ajustement du suivi inflammatoire.', 'pa17-lomb22-queue','pa17-lomb22-urgence')+
 title('9.e Adapter l’exploration aux situations particulières')+
 para('En cas d’antécédent de réaction d’hypersensibilité à un produit iodé ou gadoliné, l’ESUR recommande d’envisager une autre modalité ou un examen sans injection si sa performance permet la bonne prise en charge. L’alternative dépend donc de l’information recherchée et doit être discutée avec la radiologie, plutôt que de considérer toute imagerie comme impossible.', 'pa814-esur-allergie')+
 para('Pendant la grossesse, l’ESUR réserve l’IRM injectée à une indication très forte ; dans ce cadre, la plus faible dose possible d’un agent gadoliné macrocyclique peut être utilisée. La condition d’indication forte et le choix de l’agent doivent rester associés. Cette recommandation ne transforme donc pas l’injection en élément systématique du bilan sacro-iliaque.', 'pa814-esur-grossesse','ch-spa-2023-detail-5')+
 para('Un DFGe inférieur à 30 mL/min/1,73 m² figure parmi les situations de risque discutées par l’ESUR pour certains usages intravasculaires du contraste iodé. Une méthode alternative sans contraste iodé doit alors être envisagée selon l’indication. Le choix ne peut donc pas être réduit à une substitution automatique d’un produit par un autre, sans examiner la question diagnostique.', 'pa814-esur-renal','pa814-esur-alternative')+
 window('irmouct','IRM impossible et priorité diagnostique', 'Pour une alarme neurologique rachidienne, les HUG privilégient l’IRM et demandent au minimum un CT si nécessaire, avec avis neurochirurgical. Pour une suspicion de fracture sur rachis ankylosé, ASAS–EULAR cite l’IRM et/ou le CT. La modalité retenue doit donc être adaptée à la complication suspectée et aux possibilités immédiates.', 'pa17-lomb22-urgence','eu-asas-eular-2022-detail-54')+
 table(['Résultat ou situation','Interprétation','Conduite'],[
 [('La CRP est élevée.',['eu-asas-eular-2022-detail-40']),('L’élévation doit être attribuable à la maladie après exclusion d’autres causes plausibles.',['eu-asas-eular-2022-detail-40']),('Le résultat est intégré à la synthèse clinique et à l’évaluation d’activité.',['eu-asas-eular-2022-detail-25','eu-asas-eular-2022-detail-28'])],
 [('L’IRM montre une inflammation sacro-iliaque.',['eu-asas-eular-2022-detail-29']),('Le résultat doit être confronté à la clinique et aux causes alternatives.',['eu-asas-eular-2022-detail-40']),('Il peut contribuer à la décision lorsque l’activité inflammatoire est incertaine.',['eu-asas-eular-2022-detail-29'])],
 [('Les radiographies montrent des syndesmophytes.',['eu-asas-eular-2022-detail-29']),('Ils témoignent d’un dommage structural et possèdent une valeur pronostique.',['eu-asas-eular-2022-detail-29']),('La surveillance structurale programmée est distinguée des explorations de complications.',['eu-asas-eular-2022-detail-29','eu-asas-eular-2022-detail-54'])],
 [('Une douleur nouvelle survient sur un rachis ankylosé.',['eu-asas-eular-2022-detail-54']),('Une fracture doit être recherchée, même après traumatisme mineur.',['eu-asas-eular-2022-detail-54']),('Une IRM et/ou un CT sont réalisés selon l’évaluation, avec avis rachidien expérimenté si nécessaire.',['eu-asas-eular-2022-detail-54'])]
 ])
)

save(10,
 title('10.a Première bifurcation : complication nouvelle ou évolution habituelle')+
 para('Si une douleur nouvelle ou un changement important survient sur un rachis ankylosé, alors une fracture doit être recherchée, même après traumatisme mineur. L’évaluation comprend une imagerie appropriée par IRM et/ou CT et peut nécessiter un chirurgien rachidien expérimenté. La décision ne consiste donc pas à traiter d’emblée une poussée inflammatoire présumée.', 'eu-asas-eular-2022-detail-54')+
 para('Si une alarme neurologique est présente, alors une imagerie rachidienne doit être obtenue sans attendre, si possible par IRM et au minimum par CT, avec avis neurochirurgical. Une rétention urinaire, une anesthésie en selle ou un déficit moteur orientent cette priorité. Le calendrier de surveillance de la maladie chronique ne s’applique pas à cette branche.', 'pa17-lomb22-queue','pa17-lomb22-urgence')+
 title('10.b Deuxième bifurcation : diagnostic confirmé ou hypothèse encore à établir')+
 para('Si le diagnostic n’est pas confirmé, alors le patient est évalué par un rhumatologue qui confronte clinique, biologie et imagerie et exclut des explications plus probables. La satisfaction de critères de classification ne suffit pas à sauter cette étape. Les critères d’activité et d’éligibilité thérapeutique viennent ensuite, lorsque la maladie est établie.', 'eu-asas-eular-2022-detail-25','eu-asas-eular-2022-detail-38')+
 para('Si le diagnostic est confirmé, alors l’évaluation distingue manifestations axiales, périphériques et extramusculosquelettiques, comorbidités et facteurs psychosociaux. Ces informations orientent le traitement individualisé. La posture, la fonction et les symptômes sont donc intégrés dans un même plan clinique sans être confondus.', 'eu-asas-eular-2022-detail-24','eu-asas-eular-2022-detail-20')+
 title('10.c Troisième bifurcation : activité et stratégie initiale')+
 para('Si douleur et raideur nécessitent un traitement, alors un AINS peut constituer la première option pharmacologique après appréciation des risques et bénéfices. L’éducation, l’exercice régulier, l’arrêt du tabac et la physiothérapie gardent leur place. Le traitement médicamenteux ne remplace donc pas les mesures fonctionnelles et l’implication du patient.', 'eu-asas-eular-2022-detail-15','eu-asas-eular-2022-detail-31','eu-asas-eular-2022-detail-32')+
 para('Si les symptômes sont contrôlés sans prise continue d’AINS, alors l’usage à la demande est préféré en raison des risques d’un traitement prolongé. Si une prise continue est nécessaire, la décision reste fondée sur le contrôle des symptômes. Elle ne doit pas être justifiée par une promesse de prévention structurale qui n’est pas établie.', 'eu-asas-eular-2022-detail-34')+
 para('Si une activité élevée persiste malgré les traitements conventionnels, alors l’éligibilité à un traitement ciblé est examinée par le rhumatologue. ASAS–EULAR considère notamment l’échec d’au moins deux AINS sur une période totale de 4 semaines et privilégie l’ASDAS au moins égal à 2,1, avec avis clinique favorable. Ces éléments ne dispensent pas de vérifier les contre-indications et les données objectives pertinentes.', 'eu-asas-eular-2022-detail-41','eu-asas-eular-2022-detail-38','eu-asas-eular-2022-detail-40')+
 title('10.d Quatrième bifurcation : quelle manifestation guide le choix ciblé ?')+
 para('Si une uvéite est récidivante ou une maladie inflammatoire intestinale active, alors les recommandations privilégient un anticorps monoclonal anti-TNF. Si un psoriasis significatif prédomine, un inhibiteur d’IL-17 peut être préféré. Une maladie intestinale active contre-indique les inhibiteurs d’IL-17 dans la recommandation citée ; la stratégie ne se choisit donc pas sur le seul symptôme axial.', 'eu-asas-eular-2022-detail-47')+
 para('Si la maladie est purement axiale, alors les traitements de fond synthétiques conventionnels ne sont normalement pas retenus. Si une arthrite périphérique est présente, leur place est différente et la sulfasalazine peut être envisagée. Le territoire clinique atteint détermine donc une partie essentielle de la décision.', 'eu-asas-eular-2022-detail-37')+
 title('10.e Cinquième bifurcation : réponse, échec ou rémission')+
 para('Si la réponse est insuffisante, alors le diagnostic et les comorbidités sont réexaminés avant de changer automatiquement de traitement. Si une activité persistante est confirmée après échec d’un premier traitement ciblé, un autre traitement ciblé peut être envisagé. Les recommandations ne démontrent pas une séquence universellement supérieure pour toutes les situations d’échec.', 'eu-asas-eular-2022-detail-48','eu-asas-eular-2022-detail-49','eu-asas-eular-2022-detail-50')+
 para('Si une rémission est durable, alors une réduction progressive d’un traitement biologique peut être discutée avec réévaluations successives. L’arrêt brutal expose à davantage de poussées que le maintien ou la réduction dans les données citées. La diminution doit donc rester une décision partagée et surveillée.', 'eu-asas-eular-2022-detail-51','eu-asas-eular-2022-detail-52')+
 para('Si la déformation rachidienne est sévère et invalidante, alors une évaluation dans un centre spécialisé peut discuter une ostéotomie correctrice. Si une hanche présente douleur ou handicap réfractaire avec dommage radiographique, une arthroplastie peut être envisagée indépendamment de l’âge. Ces branches structurales répondent à un retentissement spécifique et complètent la stratégie médicale.', 'eu-asas-eular-2022-detail-53')
)

save(11,
 title('11.A Fixer un objectif clinique partagé et mesurable')+
 para('Le traitement vise la qualité de vie à long terme par le contrôle des symptômes et de l’inflammation, la prévention du dommage structural et la préservation de la fonction et de la participation sociale. Le patient et le rhumatologue définissent ensemble l’objectif. Il faut donc suivre une amélioration utile pour la personne, tout en évaluant l’activité et les risques.', 'eu-asas-eular-2022-detail-20','eu-asas-eular-2022-detail-21')+
 para('L’ASDAS guide l’évaluation d’activité, mais le bénéfice d’une stratégie strictement dirigée vers une cible demeure discuté dans ASAS–EULAR. Le score doit orienter la décision sans provoquer une intensification automatique lorsque l’inflammation résiduelle n’est pas convaincante. Les comorbidités et le contexte peuvent modifier les symptômes et doivent être intégrés.', 'eu-asas-eular-2022-detail-30','eu-asas-eular-2022-detail-49')+
 title('11.B.1 🚩 Traiter la situation urgente avant la stratégie chronique')+
 para('Une douleur nouvelle sur rachis ankylosé doit faire rechercher une fracture, même après un faible traumatisme. Une IRM et/ou un CT sont alors réalisés selon l’évaluation, avec recours possible à un chirurgien rachidien expérimenté. La recherche de complication précède l’ajustement d’un traitement anti-inflammatoire supposé insuffisant.', 'eu-asas-eular-2022-detail-54')+
 window('urgence','Urgence — conduite chronologique', 'Devant une modification importante du cours clinique, rechercher une cause autre que l’inflammation, notamment une fracture ; obtenir l’imagerie adaptée et solliciter l’expertise rachidienne selon la situation. Devant des signaux neurologiques, les HUG demandent une imagerie sans attendre, si possible une IRM et au minimum un CT, avec avis neurochirurgical.', 'eu-asas-eular-2022-detail-54','pa17-lomb22-urgence')+
 title('11.B.2 Associer éducation, exercice et traitement médicamenteux')+
 para('L’éducation comprend la compréhension de la maladie, de ses symptômes, de son évolution, des options thérapeutiques et du pronostic. L’exercice régulier constitue une composante centrale de la prise en charge et la physiothérapie doit être envisagée. L’activité supervisée a montré un intérêt supérieur à des exercices uniquement réalisés à domicile dans les données discutées, sans permettre de désigner une série universelle d’exercices optimale.', 'eu-asas-eular-2022-detail-31','eu-asas-eular-2022-detail-32')+
 para('L’arrêt du tabac est recommandé, le tabagisme étant associé à l’inflammation rachidienne et à la progression. L’adaptation au patient tient compte de ses manifestations, de ses comorbidités et de ses contraintes psychosociales. La coordination multidisciplinaire relève du rhumatologue.', 'eu-asas-eular-2022-detail-33','eu-asas-eular-2022-detail-24','eu-asas-eular-2022-detail-14')+
 title('11.B.3 Celebrex® : un exemple AIPS dont les conditions doivent rester visibles')+
 para('L’information professionnelle suisse de Celebrex® inclut le traitement symptomatique de l’inflammation et des douleurs de la spondylarthrite ankylosante. Le numéro d’autorisation est 54994 et l’information consultée est datée de juin 2025. La décision d’utiliser ce traitement dépend de l’ensemble des facteurs de risque individuels.', 'aips-54994-4-1','aips-54994-17-1','aips-54994-20-1')+
 para('Chez l’adulte atteint de spondylarthrite ankylosante, l’AIPS recommande 200 mg par jour en une prise ou répartis en deux prises. Si le soulagement est insuffisant, une augmentation à 400 mg par jour en une prise ou répartis en deux prises peut être bénéfique ; la dose quotidienne maximale adulte est de 400 mg. Si aucune amélioration ne survient dans les deux semaines après adaptation, d’autres options doivent être envisagées.', 'aips-54994-5-2')+
 para('Les gélules se prennent par voie orale avec de l’eau, pendant ou en dehors des repas. L’AIPS demande la plus faible dose efficace pendant la durée la plus courte possible, avec réévaluation du besoin et de la réponse. La dose maximale n’est donc pas une consigne de départ systématique ni une durée de traitement prédéfinie.', 'aips-54994-5-4','aips-54994-5-1','aips-54994-5-2')+
 table(['Médicament','Dose adulte pour la spondylarthrite ankylosante','Voie et durée','Restrictions majeures','Preuve AIPS'],[
 [('Le célécoxib est commercialisé ici sous Celebrex®.',['aips-54994-4-1']),('La dose recommandée est de 200 mg/jour ; une augmentation à 400 mg/jour peut être discutée si le soulagement est insuffisant, sans dépasser ce maximum adulte.',['aips-54994-5-2']),('La prise est orale, avec ou sans repas ; la dose efficace minimale et la durée la plus courte sont recherchées.',['aips-54994-5-4','aips-54994-5-1']),('Grossesse, allaitement, maladie inflammatoire intestinale et insuffisance rénale sévère figurent notamment parmi les contre-indications.',['aips-54994-6-1']),('L’autorisation Swissmedic est 54994 ; la section posologique distingue explicitement la spondylarthrite ankylosante.',['aips-54994-17-1','aips-54994-5-2'])]
 ])+
 para('Une maladie inflammatoire intestinale, un ulcère gastroduodénal actif ou une hémorragie digestive contre-indiquent Celebrex® dans l’AIPS. Cette restriction est particulièrement importante dans la spondylarthrite, car une atteinte intestinale peut appartenir au tableau associé. Une recommandation générale en faveur des AINS ne justifie donc pas ce produit chez tous les patients.', 'aips-54994-6-1','eu-asas-eular-2022-detail-5','eu-asas-eular-2022-detail-15')+
 para('Les autres contre-indications incluent notamment une hypersensibilité aux sulfonamides, certaines réactions à l’aspirine ou aux AINS, une insuffisance cardiaque NYHA II–IV, une coronaropathie ou une affection cérébrovasculaire cliniquement établie, ainsi qu’une insuffisance hépatique sévère. Ces exclusions doivent être recherchées avant la prescription et ne sont pas levées par la seule présence d’une douleur importante.', 'aips-54994-6-1')+
 title('11.B.4 Situations particulières : appliquer l’AIPS à la bonne population')+
 para('Celebrex® est contre-indiqué pendant la grossesse et doit être arrêté si une grossesse survient sous traitement. Les femmes en âge de procréer doivent utiliser une contraception sûre pendant le traitement et jusqu’à une semaine après. L’allaitement figure également parmi les contre-indications ; si le traitement est indispensable, l’AIPS prévoit une alimentation de substitution du nourrisson.', 'aips-54994-9-1','aips-54994-9-3','aips-54994-6-1')+
 para('Une insuffisance rénale sévère, définie dans l’AIPS par une clairance de créatinine inférieure à 30 mL/min, contre-indique le célécoxib. Les expériences en insuffisance rénale légère ou modérée sont limitées et imposent la prudence. Ce seuil de clairance propre à la notice ne doit pas être confondu avec un seuil de DFGe exprimé pour un autre usage, par exemple l’imagerie.', 'aips-54994-6-1','aips-54994-5-2','aips-54994-5-3','pa814-esur-renal')+
 para('En insuffisance hépatique modérée avec manifestations cliniques et albuminémie entre 25 et 35 g/L, l’AIPS demande de commencer avec des doses réduites de moitié. L’insuffisance hépatique sévère reste contre-indiquée. Chez un métaboliseur lent connu ou suspecté du CYP2C9, il faut envisager de commencer par la moitié de la plus faible dose recommandée.', 'aips-54994-5-2','aips-54994-6-1','aips-54994-5-4')+
 para('Chez la personne âgée, la dose initiale indiquée reste de 200 mg/jour, avec une prudence particulière lorsque le poids est inférieur à 50 kg. La surveillance doit tenir compte de la fonction rénale, hépatique et cardiaque, plus souvent altérée dans cette population. La situation clinique individuelle prime donc sur une simple reproduction du schéma adulte.', 'aips-54994-5-3','aips-54994-7-8')+
 para('La rubrique pédiatrique de cette AIPS porte sur l’arthrite juvénile idiopathique, avec des conditions propres de poids et de dose. Elle ne doit pas être transformée en un schéma universel pour une déformation rachidienne chez l’enfant. L’indication et la population doivent rester celles effectivement décrites dans la notice.', 'aips-54994-4-1','aips-54994-5-3')+
 title('11.B.5 Escalade spécialisée et manifestations associées')+
 para('Une activité persistante élevée malgré les traitements conventionnels peut conduire à discuter un anti-TNF, un inhibiteur d’IL-17 ou un inhibiteur de JAK. Dans les recommandations ASAS–EULAR de 2022, la pratique décrite commence généralement par un anti-TNF ou un inhibiteur d’IL-17. Le choix exige une évaluation de l’activité, des manifestations associées et des risques individuels.', 'eu-asas-eular-2022-detail-38','eu-asas-eular-2022-detail-42','eu-asas-eular-2022-detail-24')+
 para('Les anticorps monoclonaux anti-TNF sont privilégiés en cas d’uvéites récidivantes ou de maladie intestinale active ; un inhibiteur d’IL-17 peut être préféré en cas de psoriasis significatif. Les inhibiteurs d’IL-17 sont contre-indiqués en présence d’une maladie inflammatoire intestinale active dans cette recommandation. Les traitements ne sont donc pas interchangeables pour toutes les manifestations.', 'eu-asas-eular-2022-detail-47')+
 para('Les glucocorticoïdes systémiques prolongés ne sont pas recommandés pour l’atteinte axiale. Les traitements de fond synthétiques conventionnels ne sont normalement pas utilisés dans la maladie purement axiale, tandis que la sulfasalazine peut avoir une place en présence d’arthrite périphérique. Le territoire de la maladie doit donc rester explicite lors du choix thérapeutique.', 'eu-asas-eular-2022-detail-36','eu-asas-eular-2022-detail-37')+
 title('11.C Surveiller l’efficacité et les risques')+
 para('Sous célécoxib, la pression artérielle doit être étroitement surveillée au début et pendant le traitement. Une rétention hydrique, des œdèmes et une néphrotoxicité sont possibles ; les patients âgés ou ayant une atteinte rénale, cardiaque ou hépatique nécessitent une surveillance attentive. L’association avec d’autres AINS doit être évitée.', 'aips-54994-7-5','aips-54994-7-6','aips-54994-7-2')+
 para('Le traitement doit être interrompu au moindre rash cutané, à une lésion des muqueuses ou à des signes d’hypersensibilité. Une aggravation de la fonction rénale, hépatique ou cardiaque conduit également à envisager les mesures nécessaires et l’arrêt du célécoxib. Ces consignes d’arrêt doivent être connues du patient et intégrées à la réévaluation.', 'aips-54994-7-7','aips-54994-7-8')+
 para('L’association aux anticoagulants oraux augmente le risque de saignement. Chez les patients sous warfarine ou produit comparable, l’INR doit être contrôlé au début du traitement ou après modification de la dose de célécoxib. L’histoire médicamenteuse complète est donc nécessaire avant de considérer le traitement comme sûr.', 'aips-54994-7-8','aips-54994-7-9')+
 para('Pour un traitement biologique ou synthétique ciblé, ASAS–EULAR propose une appréciation de la réponse après au moins 12 semaines, avec une amélioration de l’ASDAS d’au moins 1,1 et l’avis favorable du rhumatologue pour poursuivre. La décision reste partagée et ne repose pas uniquement sur le chiffre. Si la réponse manque, le diagnostic et les comorbidités doivent être réexaminés.', 'eu-asas-eular-2022-detail-45','eu-asas-eular-2022-detail-48','eu-asas-eular-2022-detail-49')+
 title('11.D Fonction, rémission, recours chirurgical et continuité des soins')+
 para('Une rémission durable peut permettre d’envisager une réduction progressive d’un traitement biologique, avec réévaluations avant chaque étape. ASAS–EULAR retient par accord du groupe une période d’au moins 6 mois avant cette discussion, tout en reconnaissant que la définition de la rémission durable n’est pas formellement établie. Il ne s’agit donc pas d’un arrêt automatique à une date donnée.', 'eu-asas-eular-2022-detail-51','eu-asas-eular-2022-detail-52')+
 para('Une déformation sévère et invalidante peut motiver une discussion d’ostéotomie dans un centre spécialisé. Une destruction symptomatique de hanche peut relever d’une arthroplastie, indépendamment de l’âge. Ces décisions s’appuient sur le dommage et le handicap et s’inscrivent dans une prise en charge coordonnée.', 'eu-asas-eular-2022-detail-53')+
 para('Les difficultés professionnelles, les arrêts de travail et la participation sociale font partie des conséquences de la maladie à prendre en compte. Le plan de soins doit donc expliciter les besoins fonctionnels et les objectifs du patient, en lien avec la coordination multidisciplinaire. La rémission ne signifie pas que les conséquences structurales ou sociales cessent automatiquement d’exister.', 'eu-asas-eular-2022-detail-22','eu-asas-eular-2022-detail-20','eu-asas-eular-2022-detail-14')
)

save(12,
 title('12.a Prévenir les conséquences par une participation active aux soins')+
 para('L’éducation recommandée par ASAS–EULAR porte sur les symptômes, leur reconnaissance, l’évolution, les options de traitement et le pronostic. Elle vise à rendre le patient acteur de sa prise en charge. Une compréhension claire des signes habituels et des situations nouvelles aide donc à organiser le recours aux soins.', 'eu-asas-eular-2022-detail-31','eu-asas-eular-2022-detail-54')+
 para('L’exercice régulier reste une composante centrale du traitement, avec des bénéfices indépendants de la pharmacothérapie. La physiothérapie, notamment supervisée, peut améliorer l’adhésion et l’efficacité par rapport à des exercices uniquement réalisés à domicile. Le programme doit néanmoins être individualisé, car les données discutées ne permettent pas de désigner un ensemble universel d’exercices supérieur.', 'eu-asas-eular-2022-detail-32')+
 title('12.b Agir sur un facteur associé à la progression')+
 para('Le tabagisme est associé à l’inflammation rachidienne et à la progression de la spondylarthrite. L’arrêt du tabac est recommandé, mais ASAS–EULAR distingue cette recommandation des données directes sur le bénéfice propre du sevrage dans la maladie. Il faut donc proposer l’arrêt sans promettre une réduction chiffrée d’ankylose non démontrée dans la source.', 'eu-asas-eular-2022-detail-33')+
 para('Les facteurs cardiovasculaires et les comorbidités participent aussi au choix des médicaments. L’AIPS de Celebrex® impose une évaluation attentive chez les patients présentant des facteurs de risque cardiovasculaire et des restrictions en cas de maladie cardiovasculaire établie. La prévention de la toxicité dépend donc d’une prescription adaptée au terrain.', 'aips-54994-7-4','aips-54994-6-1')+
 title('12.c Reconnaître tôt une complication sans multiplier les examens inutiles')+
 para('Une douleur nouvelle ou un changement important du cours clinique doit faire rechercher une fracture sur rachis ankylosé. La vigilance concerne aussi les traumatismes jugés mineurs. Cette consigne donne au patient un motif concret de réévaluation plutôt qu’une injonction vague à surveiller sa maladie.', 'eu-asas-eular-2022-detail-54')+
 para('Le suivi régulier combine symptômes, examen, biologie et imagerie pertinente, avec une fréquence individualisée. L’IRM ne constitue pas une surveillance systématique de routine ; elle répond à une question clinique, notamment une incertitude inflammatoire. La prévention des complications ne se confond donc pas avec la répétition indifférenciée des examens.', 'eu-asas-eular-2022-detail-26','eu-asas-eular-2022-detail-29')+
 window('surveillance','Ce qu’un suivi complet cherche à préserver', 'Le suivi doit apprécier les manifestations de la maladie, la fonction et les objectifs du patient, tout en surveillant les risques du traitement. ASAS–EULAR recommande une évaluation initiale et une revue globale annuelle en complément d’une fréquence de contrôle adaptée à la situation. L’objectif demeure la qualité de vie et la participation.', 'eu-asas-eular-2022-detail-28','eu-asas-eular-2022-detail-20')+
 title('12.d Prévenir les dommages liés au traitement et préserver la fonction')+
 para('La prise continue d’AINS est réservée au besoin de contrôle des symptômes ; elle ne doit pas être motivée par une promesse de prévention du dommage structural. Lorsque le contrôle ne nécessite pas de prise continue, ASAS–EULAR préfère une prise à la demande. Cette règle contribue à limiter l’exposition prolongée aux risques.', 'eu-asas-eular-2022-detail-34')+
 para('Sous célécoxib, l’information sur les éruptions, les lésions muqueuses et les signes d’hypersensibilité doit accompagner la prescription, puisque leur survenue impose l’arrêt. La surveillance de la pression artérielle et des fonctions à risque participe également à la prévention iatrogène. Ces mesures sont aussi importantes que la recherche d’efficacité antalgique.', 'aips-54994-7-7','aips-54994-7-5','aips-54994-7-8')+
 para('La réduction d’un traitement biologique en rémission doit être progressive et réévaluée. Les arrêts brutaux exposent à des rechutes dans les données discutées. Préserver la fonction exige donc une continuité du suivi et une décision partagée, même lorsque les symptômes se sont améliorés.', 'eu-asas-eular-2022-detail-51','eu-asas-eular-2022-detail-52')
)

save(13,
 para('Une douleur nouvelle sur rachis ankylosé impose de rechercher une fracture, même après un traumatisme mineur, avec une imagerie adaptée.', 'eu-asas-eular-2022-detail-54')+
 para('Le diagnostic de spondylarthrite axiale relève d’une synthèse spécialisée clinique, biologique et radiologique ; les critères de classification ne le remplacent pas.', 'eu-asas-eular-2022-detail-25')+
 para('L’activité inflammatoire, le dommage structural et le retentissement fonctionnel doivent être évalués séparément puis réunis dans la décision thérapeutique.', 'eu-asas-eular-2022-detail-20','eu-asas-eular-2022-detail-28','eu-asas-eular-2022-detail-29')+
 para('L’exercice, l’éducation et la physiothérapie complètent le traitement médicamenteux ; une activité persistante nécessite une réévaluation spécialisée.', 'eu-asas-eular-2022-detail-31','eu-asas-eular-2022-detail-32','eu-asas-eular-2022-detail-38')+
 para('Celebrex® ne convient pas à tous les patients atteints de spondylarthrite : une maladie inflammatoire intestinale, une grossesse ou une insuffisance rénale sévère font notamment partie de ses contre-indications.', 'aips-54994-6-1')+
 para('Une absence de réponse conduit à réexaminer le diagnostic et les comorbidités avant une escalade immunosuppressive automatique.', 'eu-asas-eular-2022-detail-48','eu-asas-eular-2022-detail-49')
)

save(14,
 title('14.a Distinguer le diagnostic de ses outils')+
 table(['Question d’examen','Réponse','Raison'],[
 [('Un résultat HLA-B27 positif confirme-t-il à lui seul la maladie ?',['ch-spa-2023-detail-3','eu-asas-eular-2022-detail-25']),('Non : il doit être interprété avec la clinique, la biologie pertinente et l’imagerie.',['eu-asas-eular-2022-detail-25']),('Seule une minorité des porteurs développe une spondylarthropathie dans la présentation des HUG.',['ch-spa-2023-detail-3'])],
 [('Les critères de classification peuvent-ils remplacer la confirmation par le rhumatologue ?',['eu-asas-eular-2022-detail-25']),('Non : le diagnostic est une synthèse clinique spécialisée.',['eu-asas-eular-2022-detail-25']),('La classification sert à constituer des populations homogènes pour la recherche.',['eu-asas-eular-2022-detail-25'])],
 [('Un ASDAS élevé suffit-il à décider une intensification ?',['eu-asas-eular-2022-detail-30','eu-asas-eular-2022-detail-41']),('Non : le score doit être complété par l’avis clinique et la recherche d’une inflammation résiduelle convaincante.',['eu-asas-eular-2022-detail-30','eu-asas-eular-2022-detail-41']),('Des comorbidités peuvent influencer l’activité ressentie.',['eu-asas-eular-2022-detail-49'])],
 [('L’IRM est-elle imposée à chaque contrôle de routine ?',['eu-asas-eular-2022-detail-29']),('Non : elle peut aider lorsque l’origine des plaintes ou l’activité inflammatoire est incertaine.',['eu-asas-eular-2022-detail-29']),('Sa valeur en surveillance systématique n’est pas établie et son emploi fréquent n’est pas recommandé.',['eu-asas-eular-2022-detail-29'])]
 ])+
 title('14.b Reconnaître une complication derrière un diagnostic connu')+
 para('Question : une douleur apparue après un traumatisme minime peut-elle être traitée comme une simple poussée chez un patient ankylosé ? Réponse : il faut rechercher une fracture et réaliser l’évaluation appropriée. La raison est que le rachis ankylosé peut se fracturer après un événement mineur, avec un pronostic potentiellement plus défavorable.', 'eu-asas-eular-2022-detail-54')+
 para('Question : le délai d’au moins 2 ans entre radiographies structurales empêche-t-il d’obtenir une imagerie pour une douleur nouvelle ? Réponse : non, ce délai concerne la surveillance de la progression structurale. Une suspicion de fracture relève d’une autre indication et peut requérir une IRM et/ou un CT sans attendre ce calendrier.', 'eu-asas-eular-2022-detail-29','eu-asas-eular-2022-detail-54')+
 para('Question : une rétention urinaire ou une anesthésie en selle peut-elle attendre le prochain contrôle de rhumatologie ? Réponse : ces signaux d’alarme neurologique justifient une imagerie sans attendre et un avis neurochirurgical selon la stratégie des HUG. Le diagnostic chronique connu ne doit donc pas masquer la nouvelle urgence.', 'pa17-lomb22-queue','pa17-lomb22-urgence')+
 title('14.c Respecter la population et les contre-indications d’une posologie')+
 para('Question : peut-on prescrire Celebrex® à toute personne douloureuse atteinte de spondylarthrite ? Réponse : non, il faut rechercher les contre-indications de l’AIPS. Une maladie inflammatoire intestinale, une grossesse, l’allaitement, une insuffisance rénale sévère ou certaines maladies cardiovasculaires en font notamment partie ; la recommandation de classe ne supprime pas ces restrictions.', 'aips-54994-6-1','eu-asas-eular-2022-detail-15')+
 para('Question : la dose maximale adulte est-elle la dose initiale obligatoire ? Réponse : non, l’AIPS recommande 200 mg/jour pour la spondylarthrite ankylosante et permet une augmentation à 400 mg/jour si le soulagement est insuffisant, avec réévaluation. La dose efficace la plus faible et la durée la plus courte doivent être recherchées.', 'aips-54994-5-2','aips-54994-5-1')+
 para('Question : une dose pédiatrique publiée sous la rubrique arthrite juvénile peut-elle devenir automatiquement une prescription pour une déformation du dos chez l’enfant ? Réponse : non, la rubrique a une indication et des conditions de poids propres. La population et l’indication de l’extrait doivent accompagner la posologie.', 'aips-54994-4-1','aips-54994-5-3')+
 para('Question : un rash apparu sous célécoxib peut-il être surveillé en poursuivant systématiquement le produit ? Réponse : l’AIPS demande l’interruption au moindre rash, à une lésion muqueuse ou à un signe d’hypersensibilité. Cette consigne vise à éviter la poursuite d’un traitement dans un contexte de réaction potentiellement grave.', 'aips-54994-7-7','aips-54994-7-6')+
 title('14.d Ne pas confondre les territoires de maladie ni les objectifs du traitement')+
 para('Question : les traitements synthétiques conventionnels d’une arthrite périphérique doivent-ils être utilisés de la même manière dans une atteinte purement axiale ? Réponse : non, ASAS–EULAR ne les recommande normalement pas pour la maladie purement axiale et distingue leur place dans l’arthrite périphérique. Le territoire clinique conditionne donc leur pertinence.', 'eu-asas-eular-2022-detail-37')+
 para('Question : une uvéite récidivante et un psoriasis important orientent-ils obligatoirement vers le même traitement ciblé ? Réponse : non, les recommandations privilégient un anticorps monoclonal anti-TNF pour des uvéites récidivantes ou une atteinte intestinale active, tandis qu’un inhibiteur d’IL-17 peut être préféré pour un psoriasis significatif. Les manifestations associées doivent donc être connues avant de choisir.', 'eu-asas-eular-2022-detail-47')+
 para('Question : faut-il poursuivre un AINS en continu uniquement pour prévenir les lésions structurales ? Réponse : non, ASAS–EULAR fonde ce choix sur la nécessité de contrôler les symptômes. Les données sur la prévention structurale ne justifient pas cette prescription continue à elles seules.', 'eu-asas-eular-2022-detail-34')+
 para('Question : une rémission permet-elle d’arrêter brutalement le traitement biologique ? Réponse : les recommandations envisagent plutôt une diminution progressive, avec réévaluations et décision partagée. Les données discutées montrent davantage de poussées après arrêt brutal que lors d’un maintien ou d’une réduction.', 'eu-asas-eular-2022-detail-51','eu-asas-eular-2022-detail-52')+
 para('Ce cours, lu seul avec ses fenêtres, suffit-il pour gagner 90 à 100 % des points sur ce sujet et pour traiter ce patient en sécurité ?', 'prompt-question-finale')
)

